CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, price INTEGER NOT NULL, price_old INTEGER, description_short TEXT, description_long TEXT, image_main TEXT, image_gallery TEXT, category TEXT, in_stock INTEGER NOT NULL DEFAULT 1, stock_qty INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, published INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_products_published ON products(published, sort_order);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category);
CREATE INDEX IF NOT EXISTS idx_products_slug ON products(slug);
CREATE TABLE IF NOT EXISTS articles (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, excerpt TEXT, thumbnail TEXT, content_md TEXT NOT NULL, author TEXT, status TEXT NOT NULL DEFAULT 'draft', published_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_articles_status ON articles(status, published_at DESC);
CREATE INDEX IF NOT EXISTS idx_articles_slug ON articles(slug);
CREATE TABLE IF NOT EXISTS banners (id INTEGER PRIMARY KEY AUTOINCREMENT, slot TEXT NOT NULL UNIQUE, image_url TEXT, eyebrow TEXT, title_line1 TEXT, title_line2 TEXT, tagline TEXT, cta_text TEXT, cta_link TEXT, enabled INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_banners_slot ON banners(slot);
CREATE TABLE IF NOT EXISTS site_config (key TEXT PRIMARY KEY, value TEXT, updated_at TEXT NOT NULL DEFAULT (datetime('now')));
INSERT OR IGNORE INTO banners (slot, image_url, eyebrow, title_line1, title_line2, tagline, cta_text, cta_link) VALUES ('home_1', 'images/banner-1.jpg', '/ Trang chủ · Slide 1', 'Năng lượng.', 'Không giới hạn.', 'Sạc dự phòng, ổ điện du lịch, sạc dây rút — chuẩn quốc tế, giá tốt nhất Việt Nam.', 'Khám phá sản phẩm', '#products'), ('home_2', 'images/banner-2.jpg', '/ Trang chủ · Slide 2', 'Du lịch.', 'Không lo điện.', 'Ổ điện 65W và 100W LED, đa quốc gia, gọn nhẹ trong túi xách.', 'Xem ổ điện', 'products/sl207.html'), ('home_3', 'images/banner-3.jpg', '/ Trang chủ · Slide 3', 'Sạc nhanh.', 'Mọi lúc.', 'JP395 10000mAh - sạc đầy iPhone 3 lần, nhỏ gọn vừa lòng bàn tay.', 'Xem sạc dự phòng', 'products/jp395.html'), ('b2b_1', 'images/banner-b2b-1.jpg', '/ B2B · Corporate gifts', 'Quà tặng', 'đẳng cấp.', 'Giải pháp quà tặng kỹ thuật cao cho doanh nghiệp Việt. Chất lượng quốc tế, giá đại lý cạnh tranh.', 'Nhận báo giá', '#b2b-inquiry'), ('b2b_2', 'images/banner-b2b-2.jpg', '/ Co-branding · Custom', 'In logo', 'miễn phí.', 'Khắc laser, in UV logo công ty trên từng sản phẩm. Miễn phí từ 100 đơn vị.', 'Xem ưu đãi', '#b2b-tiers'), ('b2b_3', 'images/banner-b2b-3.jpg', '/ Wholesale · Bulk pricing', 'Giá đại lý', 'từ 50 sp.', 'Tiết kiệm tới 35% so với giá bán lẻ. Báo giá chi tiết trong 24h giờ hành chính.', 'Tải catalogue', '#b2b-catalogue');
INSERT OR IGNORE INTO site_config (key, value) VALUES ('hotline', '+84 900 000 000'), ('hotline_label', 'Hotline Yokool'), ('zalo_link', 'https://zalo.me/yokool'), ('zalo_label', 'Zalo Yokool'), ('messenger_link', 'https://m.me/yokool'), ('messenger_label', 'Messenger'), ('b2b_email', 'b2b@yokool.vn'), ('b2b_hotline', '+84 900 000 000'), ('b2b_hotline_owner', 'Mr. Trường'), ('office_address', 'Tầng X, Toà Y, Quận Z, TP. Hà Nội'), ('work_hours', 'T2–T6 · 8h30 – 17h30'), ('shopee_link', 'https://shopee.vn/yokool'), ('footer_tagline', 'Năng lượng. Không giới hạn.'), ('footer_about', 'Yokool — thương hiệu công nghệ năng lượng di động Made in Vietnam, đạt chuẩn quốc tế CE/FCC/RoHS.'), ('footer_copyright', '© 2026 YOKOOL. Made in Vietnam.'), ('footer_version', 'v3.4');
INSERT OR IGNORE INTO products (code, name, slug, price, description_short, description_long, image_main, category, sort_order) VALUES ('JP395', 'Sạc dự phòng JP395 10000mAh', 'jp395', 390000, 'Sạc dự phòng 10000mAh, sạc nhanh 22.5W, có đèn LED báo dung lượng.', 'JP395 là mẫu sạc dự phòng cao cấp với dung lượng thực 10000mAh, sạc nhanh 22.5W PD. Vỏ kim loại nhám chống vân tay, kích thước gọn nhẹ vừa lòng bàn tay. Cổng vào USB-C, cổng ra USB-A và USB-C, có thể sạc 2 thiết bị cùng lúc. LED 4 đèn báo dung lượng. Pin Lithium polymer Hàn Quốc, bảo hành 12 tháng.', 'images/products/jp395.jpg', 'powerbank', 1), ('RC502', 'Sạc dây rút RC502 30W', 'rc502', 290000, 'Sạc dây rút 30W tiện lợi, đầu USB-C + Lightning, dài 0.6m.', 'RC502 - giải pháp sạc thông minh cho mọi tình huống. Dây rút có thể kéo dài tối đa 0.6m, đầu vào USB-C 30W PD. Hỗ trợ sạc nhanh cho cả iPhone (Lightning) và Android (USB-C). Vật liệu vỏ ABS chống cháy, dây cáp TPE bền. Phù hợp túi xách, vali du lịch.', 'images/products/rc502.jpg', 'powerbank', 2), ('SL207', 'Ổ điện du lịch SL207 65W', 'sl207', 590000, 'Ổ điện đa quốc gia 65W, USB-C PD, USB-A, ổ AC, phù hợp 150+ quốc gia.', 'SL207 - ổ điện du lịch tích hợp 65W GaN III, dùng được tại 150+ quốc gia với 4 chuẩn cắm AU/EU/UK/US. 1 cổng USB-C PD 65W, 2 cổng USB-A QC 18W, 1 ổ AC universal. Đèn LED báo trạng thái, chống quá tải, bảo vệ ngắn mạch. Trọng lượng 180g, kích thước 75x52x40mm.', 'images/products/sl207.jpg', 'travel', 3), ('OL212', 'Ổ điện du lịch OL212 100W LED', 'ol212', 990000, 'Ổ điện 100W GaN, màn hình LED hiển thị, đa quốc gia, sạc laptop.', 'OL212 - flagship dòng ổ điện du lịch với công suất 100W GaN III, đủ sạc MacBook Pro 16 inch. Màn hình LED hiển thị công suất real-time từng cổng. 2 USB-C PD 100W, 2 USB-A QC, 1 ổ AC universal. Hỗ trợ 150+ quốc gia. Vỏ kim loại nhôm tản nhiệt tốt, đèn LED báo trạng thái. Bảo hành 12 tháng.', 'images/products/ol212.jpg', 'travel', 4);
